    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            candidates.append((r, 'row', row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            candidates.append((c, 'col', vals[0]))
    # Prefer a single central uniform line (the examples use 5 or 0).
    pos, axis, _ = min(candidates, key=lambda z: (0 if z[1] == 'row' else 1, abs(z[0] - ((h if z[1] == 'row' else w) - 1) / 2)))
    if axis == 'row':
        a, b = grid[:pos], grid[pos + 1:]
        outbg = Counter(v for row in a for v in row).most_common(1)[0][0]
        return [[3 if x == y else outbg for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
    a = [row[:pos] for row in grid]
    b = [row[pos + 1:] for row in grid]
    outbg = Counter(v for row in a for v in row).most_common(1)[0][0]
    return [[3 if x == y else outbg for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
