 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find a uniform divider row or column separating equal-sized panels.
    separators = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            separators.append((r, "row", row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            separators.append((c, "col", vals[0]))
    # ARC examples use one divider; select the line closest to the center.
    pos, axis, _ = min(
        separators,
        key=lambda item: abs(item[0] - ((h if item[1] == "row" else w) - 1) / 2),
    )
    if axis == "row":
        first, second = grid[:pos], grid[pos + 1:]
    else:
        first = [row[:pos] for row in grid]
        second = [row[pos + 1:] for row in grid]
    common = set(v for row in first for v in row) & set(v for row in second for v in row)
    # The two panels share the background/overlap color. Highlight aligned
    # occurrences of that color with 3 and retain the shared color elsewhere.
    shared = next(iter(common))
    return [[3 if x == shared and y == shared else shared for x, y in zip(a, b)]
            for a, b in zip(first, second)]
