{
 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid divider separates the patterned panel from the distractor panel.
    row_div = next((r for r, row in enumerate(grid) if len(set(row)) == 1), None)
    if row_div is not None:
        panel = grid[:row_div]
    else:
        # The divider is a uniform column; use the panel to its left.
        col_div = next(c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1)
        panel = [row[:col_div] for row in grid]
    counts = Counter(v for row in panel for v in row)
    background = counts.most_common(1)[0][0]
    foregrounds = set(counts) - {background}
    foreground = max(foregrounds, key=lambda v: counts[v]) if foregrounds else background
    return [[3 if v == foreground else background for v in row] for row in panel]
