 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the uniform divider between equal-sized panels.
    split = None
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h // 2:
            split = ("row", r)
            break
    if split is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w // 2:
                split = ("col", c)
                break
    if split is None:
        raise ValueError("No centered uniform divider found")
    axis, pos = split
    if axis == "row":
        first, second = grid[:pos], grid[pos + 1:]
    else:
        first = [row[:pos] for row in grid]
        second = [row[pos + 1:] for row in grid]
    common = set(v for row in first for v in row) & set(v for row in second for v in row)
    if len(common) != 1:
        raise ValueError(f"Expected one shared panel color, got {common}")
    shared = next(iter(common))
    return [[3 if a == shared and b == shared else shared
             for a, b in zip(row_a, row_b)]
            for row_a, row_b in zip(first, second)]
